def map_stages(df):
    STAGE_OUTCOME = {
        "Proposal": "open",
        "Prospecting": "open",
        "Negotiation": "open",
        "Closed Lost": "lost",
        "Closed - Won": "won"
    }
    df["Outcome"] = [STAGE_OUTCOME.get(s, None) for s in df["Stage"]]
    return df

def map_stages(row):
    stage = row['Stage']
    if stage in ['Closed Won', 'Closed - Won']:
        return 'won'
    elif stage == 'Closed Lost':
        return 'lost'
    elif stage in ['Prospecting', 'Qualification', 'Proposal', 'Negotiation']:
        return 'open'
    else:
        return stage
